import { comparisonView } from './comparison-view.js';
import { escapeHtml as e, time } from './store.js';
import { icon } from './icons.js';
import { jobAttempts, jobSpans, jobMetrics, spanStatus, visibleJobs } from './activity-store.js';
const range = r => `${time(r[0])}–${time(r[1])}`;
const status = value => `<span class="status-label status-${value.toLowerCase().replace(/ /g, '-')}"><i></i>${e(value)}</span>`;
const button = (action, text, id, cls = '', extra = '') => `<button class="button ${cls}" data-action="${action}" ${id ? `data-id="${e(id)}"` : ''} ${extra}>${text}</button>`;
